it("prefers a fresh capability over an unresolved host card identity", async () => {
	type RestoreResult = {
		isError: false;
		structuredContent: {
			found: true;
			tool_name: string;
			data: { title: string };
			view_state: Record<string, never>;
		};
	};
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://portable-host.example" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	bridge.hostContext = {
		toolInfo: { id: "old-card", tool: { name: "query_sdk" } },
	};
	let resolveOldRestore!: (result: RestoreResult) => void;
	const oldRestore = new Promise<RestoreResult>((resolve) => {
		resolveOldRestore = resolve;
	});
	bridge.callServerTool.mockImplementation(
		async ({ name, arguments: args }) => {
			if (name !== "restore_lobu_app_result") {
				return { isError: false, structuredContent: { saved: false } };
			}
			if (!args.snapshot_capability) return oldRestore;
			if (args.snapshot_capability === "new-card-capability") {
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: {
							title: args.tool_call_id
								? "Old card selected by host ID"
								: "Fresh capability card",
						},
						view_state: {},
					},
				};
			}
			return {
				isError: false,
				structuredContent: { found: false, view_state: {} },
			};
		},
	);

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data } = useMcpApp<{ title: string }>();
		return <span>{data?.title ?? "No result"}</span>;
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: {
				tool_call_id: "old-card",
				tool_name: "query_sdk",
			},
		}),
	);

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: {},
				_meta: {
					"lobu/mcp-app-snapshot-capability": "new-card-capability",
				},
			});
		}
	});

	expect(
		await screen.findByText("Fresh capability card"),
	).toBeInTheDocument();
	expect(bridge.callServerTool).toHaveBeenCalledWith({
		name: "restore_lobu_app_result",
		arguments: { snapshot_capability: "new-card-capability" },
	});
	expect(
		screen.queryByText("Old card selected by host ID"),
	).not.toBeInTheDocument();

	await act(async () => {
		resolveOldRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "Old in-flight card" },
				view_state: {},
			},
		});
		await oldRestore;
	});
	expect(screen.getByText("Fresh capability card")).toBeInTheDocument();
	expect(screen.queryByText("Old in-flight card")).not.toBeInTheDocument();
});

