it("retains separately delivered compatibility capability for standard data", async () => {
	type RestoreResult = {
		isError: false;
		structuredContent: {
			found: true;
			tool_name: string;
			data: { title: string };
			view_state: { "details.open": true };
		};
	};
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://chatgpt.com" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	let resolveRestore!: (result: RestoreResult) => void;
	const restore = new Promise<RestoreResult>((resolve) => {
		resolveRestore = resolve;
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => {
		if (name === "restore_lobu_app_result") return restore;
		if (name === "save_lobu_app_state") {
			return { isError: false, structuredContent: { saved: true } };
		}
		return { isError: false };
	});

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title}</span>
				<span>open:{String(viewState["details.open"])}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
	act(() => {
		window.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: {
						widgetState: {
							privateContent: {
								lobuViewSnapshot: {
									version: 1,
									data: { title: "Split live result" },
									resultIdentity: "separate-standard-token",
								},
							},
						},
						toolResponseMetadata: {
							mcp_tool_result: {
								_meta: {
									"lobu/mcp-app-snapshot-capability":
										"separate-standard-token",
								},
							},
						},
					},
				},
			}),
		);
	});
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "separate-standard-token" },
		}),
	);

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({ structuredContent: { title: "Split live result" } });
		}
	});
	expect(await screen.findByText("Split live result")).toBeInTheDocument();
	await act(async () => {
		resolveRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "Split live result" },
				view_state: { "details.open": true },
			},
		});
		await restore;
	});

	expect(await screen.findByText("open:true")).toBeInTheDocument();
	expect(screen.getByText("Split live result")).toBeInTheDocument();
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "save_lobu_app_state",
			arguments: {
				tool_name: "query_sdk",
				view_state: { "details.open": true },
				snapshot_capability: "separate-standard-token",
			},
			_meta: {
				"lobu/mcp-app-snapshot-capability": "separate-standard-token",
			},
		}),
	);
});

